ruleToc.chapterList:
@js:
eval(result.match(/var comic = \{.*?\}/)[0]);
function CustomSubString(str, nStart, nLength, bHideEnglish) {
	var s = str.substring(nStart, nStart + nLength);
	return bHideEnglish == null ? s.replace(/[a-z]*/gi, "") : s
}
var nComicId = comic.id;
var strFullCode = comic.code;
var mCodes = new Array();
var nSpecialCount = 0;
for (var i = 0; i < strFullCode.length / 50; i++) {
  mCodes.push(strFullCode.substring(i * 50, (i + 1) * 50));
}
var retMatrix = new Array();
for (var i = 0; i < mCodes.length; i++) {
  var strCode = mCodes[i];
  var nEpisodeId = parseInt(CustomSubString(strCode, 0, 4));
  var nServerId = parseInt(CustomSubString(strCode, 4, 2));
  var nRnd = parseInt(CustomSubString(strCode, 6, 1));
  var nPageCount = parseInt(CustomSubString(strCode, 7, 3));
  if (nEpisodeId >= 8000) {
    nSpecialCount++;
    retMatrix[i] = '{"id":"' + i + '","title":"番外篇' + nSpecialCount +'"}';
  } else {
    var unit = (nPageCount > 50) ? "卷": "話";
    retMatrix[i] = '{"id":"' + i + '","title":"第' + nEpisodeId + unit + '"}';
  }
}
retMatrix

ruleSearch.bookList:
@js:
JSON.parse(result).BookList.slice(0, 5).map(o =>{
    var option = JSON.stringify({"method":"POST","body":"book_id=" + o.bookid});
    var detail = 'http://www.asike.top/api/detail-book,'+option;
    var J = JSON.parse(java.ajax(detail));
    return {
        name: o.bookName,
        author: o.bookAuthor,
        tags:  o.category + ','+J.book.bookScore + '分 / '+ J.book.bookStatus.replace(/已|中/, ''),
        num: J.book.bookSize + '万字',
        latest:  (J.book.totalChapter > 100) ? ('第' + J.book.totalChapter + '章') + '（' + java.timeFormat(J.book.updateTime) + '）': J.contentList.pop().chapterName + '（' + java.timeFormat(J.book.updateTime) + '）',
        intro: o.introduction,
        cover: o.bookCover,
        catalogUrl:detail
    }
});

ruleToc.chapterList:
@js:
var data=[];
var json = JSON.parse(result).book;
var id = json.bookId;
var page = parseInt(json.totalChapter / 100);
var url = 'http://www.asike.top/api/content-list/' + id + '/';
for (var i = 0; i <= page; i++) {
    var j = JSON.parse(java.ajax(url + i)).contentList;
    data = data.concat(j);
}
data.map(o=>({
    title:o.chapterName,
    url:'http://content.asike.top'+o.contentUrl
}));
